"""Render the central portfolio from versioned, curated public records."""
import csv,io,json,re,shutil
from pathlib import Path
import build_site as base
ROOT=Path(__file__).resolve().parent;SITE=ROOT/'site'
model=json.loads((ROOT/'data/projects.json').read_text());projects=model['projects'];e=base.e
resources=json.loads((ROOT/'data/resources.json').read_text())
byid={p['id']:p for p in projects}
def filename(p):return 'work-'+p['id'].lower()+'.html'
def link(p):return '<a href="'+filename(p)+'">'+e(p['name'])+'</a>'
def score(p):return '<div class="score"><strong>'+str(p['score'])+'<small>/100</small></strong><progress value="'+str(p['score'])+'" max="100" aria-label="'+e(p['name'])+' evidence readiness"></progress><span>Evidence readiness</span></div>'
def artifact_links(p):
 return '<ul>'+''.join('<li><a href="'+e(r['url'],quote=True)+'" rel="noopener">'+e(r['title'])+'</a><br><small>'+e(r['access'])+' · '+e(r['verified'])+'</small></li>' for r in p['resources'])+'</ul>' if p['resources'] else '<p>Original source is local or a reviewer-access link has not yet been verified. This dossier is a summary, not a replacement for the original evidence.</p>'
common='<div class="notice">'+e(model['score_explanation'])+' <a href="readiness.html">Read the rubric</a>.</div>'
for p in projects:
 gates=''.join('<tr><th scope="row">'+e(g['label'])+'</th><td>'+str(g['earned'])+' / '+str(g['max'])+'</td><td>'+e(g['evidence'])+'</td></tr>' for g in p['gates'])
 notebook=''
 if p['id']=='COLAB-ML':notebook='<p><a href="downloads/mnist-coursework.ipynb" download>Download MNIST review notebook</a> · <a href="downloads/sigmoid-gradients.ipynb" download>Download gradient review notebook</a></p>'
 if p['id']=='AWS-PORTFOLIO':notebook='<p><a href="demo.html">Run browser demo</a> · <a href="downloads/data-quality-walkthrough.ipynb" download>Download executable Python walkthrough</a> · <a href="downloads/portfolio-source.zip" download>Source bundle</a></p>'
 body='<section class="hero"><div class="eyebrow">'+e(p['category'])+' · '+e(' / '.join(p['platforms']))+'</div><h1>'+e(p['name'])+'</h1><p class="lead">'+e(p['purpose'])+'</p><p><strong>Recorded status:</strong> '+e(p['status'].replace('_',' ').lower())+' · Reviewed '+p['reviewed_on']+'</p>'+score(p)+'</section>'+common
 body+='<div class="grid"><section class="panel"><h2>What the work shows</h2><p>'+e(p['result'])+'</p><h3>Evidence available</h3><p>'+e(p['evidence'])+'</p></section><section class="panel"><h2>What remains</h2><p>'+e(p['next_action'])+'</p><h3>Completion gate</h3><p>'+e(p['completion_gate'])+'</p><p>'+e(p['submission_status'])+'</p></section></div>'
 body+='<section class="panel"><h2>Open the work</h2>'+notebook+artifact_links(p)+'</section><section><h2>Execution and review notes</h2><ol>'+''.join('<li>'+e(s)+'</li>' for s in p['run_steps'])+'</ol><p><strong>Requirements:</strong> '+e(p['requirements'])+'</p><p><strong>Limits:</strong> '+e(p['limitations'])+'</p></section>'
 body+='<section><h2>Why this score?</h2><div class="table-wrap"><table><thead><tr><th>Criterion</th><th>Credit</th><th>Basis</th></tr></thead><tbody>'+gates+'</tbody></table></div><p>'+e(p['scope'])+'</p></section><section class="panel"><h2>Contribution and review</h2><p>'+e(p['authorship'])+'</p><p>Suggested discussion: explain the problem, your implementation decisions, the strongest evidence, one limitation and the next experiment. Do not infer an awarded grade or accepted submission from a filename.</p></section><nav><a href="dashboard.html">Portfolio dashboard</a><a href="projects.html">All work</a><a href="review.html">Examiner guide</a></nav>'
 base.page(filename(p),p['name'],body)
def card(p):
 return '<article class="card" data-category="'+e(p['category'])+'" data-audience="'+e(' '.join(p['audiences']))+'"><span class="badge">'+e(p['category'])+' · '+e(' / '.join(p['platforms']))+'</span><h3>'+link(p)+'</h3><p>'+e(p['purpose'])+'</p>'+score(p)+'<p>'+e(p['status'].replace('_',' ').lower())+'</p><a href="'+filename(p)+'">Evidence, execution & improvement →</a></article>'
controls='<div class="filters"><label>Search work<input id="search" type="search" placeholder="Colab, Apps Script, HMM…"></label><label>Area<select id="category"><option value="">All areas</option>'+''.join('<option>'+e(x)+'</option>' for x in sorted({p['category'] for p in projects}))+'</select></label><label>Review route<select id="audience"><option value="">All work</option><option value="employer">Employer</option><option value="examiner">Examiner / academic</option></select></label></div><p id="count" role="status" aria-live="polite"></p>'
base.page('projects.html','All work','<section class="hero"><div class="eyebrow">Central work index</div><h1>Explore the work.</h1><p class="lead">'+str(len(projects))+' public dossiers connect purposes, source links, run notes and evidence-based improvement actions.</p><p>'+e(model['coverage'])+'</p></section>'+controls+'<div id="cards" class="grid">'+''.join(card(p) for p in projects)+'</div>','catalogue.js')
mean=round(sum(p['score'] for p in projects)/len(projects),1)
academic=[p for p in projects if 'examiner' in p['audiences']]
linked=sum(bool(p['resources']) for p in projects)
group_cards=''
for category in sorted({p['category'] for p in projects}):
 members=[p for p in projects if p['category']==category];average=round(sum(p['score'] for p in members)/len(members),1)
 group_cards+='<article class="panel"><h3>'+e(category)+'</h3><strong>'+str(average)+' / 100</strong><progress max="100" value="'+str(average)+'" aria-label="'+e(category)+' average evidence readiness"></progress><p>'+str(len(members))+' workstreams. Unweighted average; components may overlap.</p></article>'
priority=['AIVOUCH','APPS-SCRIPT','PROJECT-106965784f2d','COLAB-ML','FINANCE-LAB','PROJECT-ed3aa8ddd9a6']
next_rows=''.join('<tr><th scope="row">'+link(byid[i])+'</th><td>'+str(byid[i]['score'])+'/100</td><td>'+e(byid[i]['next_action'])+'</td></tr>' for i in priority)
base.page('dashboard.html','Portfolio dashboard','<section class="hero"><div class="eyebrow">Evidence snapshot · 20 September 2026</div><h1>One place to review<br>and improve the work.</h1><p class="lead">A central dashboard for applications, AI research, Colab notebooks, Google automation and academic work.</p><div class="actions"><a class="button" href="employer.html">Employer review</a><a class="button secondary" href="review.html">Examiner review</a><a class="button secondary" href="execution.html">Run & inspect</a></div></section><div class="metrics"><div><strong>'+str(mean)+'/100</strong><span>Average evidence readiness—not actual project completion</span></div><div><strong>'+str(len(projects))+'</strong><span>Public dossiers / 46 total registered workstreams</span></div><div><strong>'+str(len(resources))+'</strong><span>Curated Drive and Colab source links</span></div></div>'+common+'<section><h2>Coverage by area</h2><div class="grid">'+group_cards+'</div></section><section><h2>Highest-priority improvements</h2><div class="table-wrap"><table><thead><tr><th>Work</th><th>Readiness</th><th>Next evidence to establish</th></tr></thead><tbody>'+next_rows+'</tbody></table></div></section><section class="panel"><h2>What is live?</h2><p><strong>This portfolio dashboard:</strong> AWS CloudFront + private S3. Read-only, publicly accessible and independent of the Ubuntu machine.</p><p><strong>Browser demo:</strong> executes locally in the visitor’s browser. <strong>Original AI OS and Finance dashboards:</strong> local operational systems, not exposed through this public site. The saved Finance dashboard report describes 33 pages; current runtime health is not asserted here.</p><p><strong>Google control sheets:</strong> linked with existing permissions. <strong>Apps Script triggers and historical notebooks:</strong> status is explicitly unverified where no fresh run exists.</p><a href="platforms.html">Platform and source directory →</a></section><section><h2>Capture and review cadence</h2><div class="table-wrap"><table><thead><tr><th>Cadence</th><th>Purpose</th><th>Evidence state</th></tr></thead><tbody><tr><th>Daily</th><td>Energy Desk physical refresh; Apps Script source targets approximately 07:30 Europe/London.</td><td>Source configuration inspected; installed remote trigger unverified.</td></tr><tr><th>Weekdays</th><td>Desk reporting and market observation workflows.</td><td>Source branch inspected; capture audit still records gaps and source failures.</td></tr><tr><th>Monday / weekly</th><td>Energy composite and weekly review; local Hybrid backup.</td><td>Energy branches exist in source. A local Hybrid snapshot was verified; independent restore is still pending.</td></tr><tr><th>Monthly / before applications</th><td>Recheck permissions, references, notebook environments, evidence scores and CV alignment.</td><td>Recommended owner review, not an installed scheduler.</td></tr></tbody></table></div><p>This dashboard is a dated evidence snapshot, not a live monitoring or scheduling service.</p></section>')
selected=[byid[i] for i in ['AWS-PORTFOLIO','AIVOUCH','COLAB-ML','AIOS-CORE','APPS-SCRIPT','FINANCE-LAB']]
base.page('employer.html','Employer review','<section class="hero"><div class="eyebrow">AI engineer / solutions architect</div><h1>A focused review route.</h1><p class="lead">Start with working software and reproducibility, then inspect the decisions and limitations behind each example.</p></section><section class="panel"><h2>A ten-minute walkthrough</h2><ol><li>Run the data-quality browser demo and inspect a failing record.</li><li>Review the AWS hosting architecture, source download and verification evidence.</li><li>Read AIVouch’s API/mobile design and local validation limits.</li><li>Inspect a Colab notebook and the distinction between saved and freshly reproduced results.</li><li>Discuss one automation failure mode and the next concrete improvement.</li></ol><p>Libraries, tools and assisted implementation are part of the engineering context. Review individual contribution through explanations and evidence; the catalogue alone is not a sole-authorship claim.</p></section><div class="grid">'+''.join(card(p) for p in selected)+'</div>')
academic_rows=''.join('<tr><th scope="row">'+link(p)+'</th><td>'+e(p['purpose'])+'</td><td>'+e(p['submission_status'])+'</td></tr>' for p in academic)
base.page('review.html','Examiner review','<section class="hero"><div class="eyebrow">Academic evidence route</div><h1>Review the study,<br>the evidence and its limits.</h1><p class="lead">Reports, notebooks and written submission notes are indexed separately from formal proof of submission or examiner acceptance.</p></section><section class="panel"><h2>Submission status is not inferred</h2><p>No complete set of university submission receipts has been verified in this review. A document called “final”, “distinction” or “submission” is an artifact—not a verified grade, upload receipt or accepted final version.</p><p>The HMM dissertation has a saved technical replay and claim audit, while a later document audit states NOT_SUPERVISOR_READY. Both facts are retained.</p><h3>Recommended examination sequence</h3><ol><li>Confirm the authoritative version and the learner’s contribution.</li><li>Read the purpose, methods, baseline and evaluation limitations.</li><li>Inspect original evidence through the linked Drive or Colab item; permission may be required.</li><li>Reproduce the relevant notebook in a fresh environment and record differences.</li><li>Compare the final document against the rubric, references and submission record.</li></ol></section><div class="table-wrap"><table><thead><tr><th>Academic work</th><th>Purpose</th><th>Formal submission evidence</th></tr></thead><tbody>'+academic_rows+'</tbody></table></div><p><a href="downloads/reviewer-checklist.md" download>Download reviewer checklist</a></p>')
rows_html=''.join('<tr><th scope="row">'+e(r['title'])+'</th><td>'+link(byid[r['project_id']])+'</td><td><a href="'+e(r['url'],quote=True)+'" rel="noopener">Open original</a><br>'+e(r['access'])+'</td><td>'+e(r['verified'])+'</td></tr>' for r in resources)
base.page('platforms.html','Colab, Drive & automation','<section class="hero"><div class="eyebrow">Source and platform directory</div><h1>Colab. Drive.<br>Scripts. Dashboards.</h1><p class="lead">Original work stays at its source. This central index connects it to a purpose, review status and improvement plan.</p></section><section class="grid"><article class="panel"><h2>Colab</h2><p>Ten selected notebook links cover neural networks, gradients and financial experiments. Original access stays permission-controlled. Two inspected coursework notebooks also have sanitized downloadable review copies.</p></article><article class="panel"><h2>Google Drive</h2><p>Reports, draft studies, presentations and control sheets are linked. Existing sharing is unchanged; a link does not guarantee anonymous access.</p></article><article class="panel"><h2>Google Apps Script</h2><p>Energy Desk source is located locally: daily London-time dispatch, weekday/Monday branches, locks and QA. Remote installation and trigger state remain unverified. GmailOrganizer documentation is linked; a document export is not an executable script project.</p></article><article class="panel"><h2>Operational dashboards</h2><p>This portfolio dashboard is live. AI OS and Finance operational dashboards remain local; their credentials, controls and private data are not proxied through this site. Review summaries and control sheets are indexed here.</p></article></section><div class="table-wrap"><table><thead><tr><th>Artifact</th><th>Related work</th><th>Access</th><th>Verification</th></tr></thead><tbody>'+rows_html+'</tbody></table></div>')
base.page('execution.html','Execution & reproduction','<section class="hero"><div class="eyebrow">Run, inspect, record</div><h1>Demonstrations with<br>clear prerequisites.</h1><p class="lead">Use a bounded sample first. Keep original coursework intact and record the environment behind every new result.</p></section><div class="grid"><section class="panel"><h2>Immediate browser demo</h2><p>No account or installation required. Validate synthetic records, inspect failures and modify the input.</p><a class="button" href="demo.html">Run demonstration</a></section><section class="panel"><h2>Portable Python notebook</h2><p>Self-contained standard-library walkthrough. Download and open in Jupyter or upload through Colab’s File menu. Its code cells are executed locally during the release checks.</p><a href="downloads/data-quality-walkthrough.ipynb" download>Download runnable notebook</a></section><section class="panel"><h2>Recovered ML coursework</h2><p>Sanitized source copies with original execution metadata removed. TensorFlow rerun is still pending; runtime and training results may differ.</p><p><a href="downloads/mnist-coursework.ipynb" download>MNIST</a> · <a href="downloads/sigmoid-gradients.ipynb" download>Sigmoid gradients</a></p><a href="work-colab-ml.html">Dependencies and review notes</a></section><section class="panel"><h2>Automation review</h2><p>Inspect Energy Desk setup and dispatcher behaviour in a workbook copy. Setup changes triggers, so the portfolio does not invoke production automation.</p><a href="work-apps-script.html">Apps Script runbook</a></section></div><section class="panel"><h2>Record a reproducible run</h2><p>Record source version, environment, input snapshot, command/cells, outputs, failures and interpretation. Keep secrets outside the notebook.</p><pre>python3 -m unittest discover -s tests -v\npython3 build.py\npython3 build_hosting.py</pre><p><a href="downloads/run-record-template.md" download>Run-record template</a> · <a href="downloads/portfolio-source.zip" download>Central source bundle</a></p></section>')
rubric=''.join('<tr><th scope="row">'+e(c['label'])+'</th><td>'+str(c['max'])+'</td></tr>' for c in model['criteria'])
all_scores=''.join('<tr><th scope="row">'+link(p)+'</th><td>'+str(p['score'])+'/100</td><td>'+e(p['next_action'])+'</td></tr>' for p in sorted(projects,key=lambda p:(-p['score'],p['name'])))
base.page('readiness.html','Readiness & improvement','<section class="hero"><div class="eyebrow">Transparent assessment</div><h1>Completion needs evidence.</h1><p class="lead">Current average: '+str(mean)+'/100 for public portfolio evidence readiness. This is not an estimate of how much underlying work is finished.</p></section>'+common+'<section><h2>The 100-point rubric</h2><div class="table-wrap"><table><thead><tr><th>Criterion</th><th>Maximum</th></tr></thead><tbody>'+rubric+'</tbody></table></div><p>Located source receives partial artifact credit; inspected implementation receives more. Saved replay reports receive partial reproducibility credit; a fresh clean rebuild receives full credit. Restricted links receive partial access credit. A summary is not a complete review package. Every dossier shows the exact awarded points and evidence.</p><p>The overall value is an unweighted mean across heterogeneous workstreams; it is not a measure of hours completed, product value or degree progress. Missing or unknown evidence receives no credit in that gate. Underlying project completion remains unassessed until its own acceptance criteria are checked.</p></section><div class="table-wrap"><table><thead><tr><th>Work</th><th>Evidence readiness</th><th>Next improvement</th></tr></thead><tbody>'+all_scores+'</tbody></table></div><p><a href="downloads/portfolio-readiness.csv" download>Download readiness register</a></p>')
base.page('repository.html','Central repository','<section class="hero"><div class="eyebrow">Source of truth</div><h1>A versioned portfolio,<br>with original evidence preserved.</h1><p class="lead">Curated project records generate the dashboard, dossiers, review routes and readiness register. The source bundle includes those records and the site implementation.</p></section><div class="flow"><div><b>ORIGINALS</b>Local projects / Drive / Colab<small>Authoritative source and existing permissions</small></div><div><b>CURATED RECORDS</b>Versioned JSON<small>Purpose, evidence, scores and run notes</small></div><div><b>BUILD</b>Static HTML + downloads<small>Schema and browser verification</small></div><div><b>DEPLOY</b>Private S3 → CloudFront<small>Public read-only portfolio</small></div></div><section class="panel"><h2>What is centralised?</h2><p>Descriptions, links, evidence assessments, execution notes and improvement actions. Original private documents are not copied wholesale to the public website. There is no public write API or automatic execution of private notebooks and workflows.</p><p><a href="downloads/portfolio-source.zip" download>Download central source</a> · <a href="downloads/portfolio-records.json" download>Public project records</a> · <a href="downloads/run-record-template.md" download>Execution notes template</a></p><h3>Owner workflow</h3><p>Update the curated records, attach evidence for any changed score, rebuild, test and deploy. Private working notes live in the local owner workspace and can be exported; they are not secretly saved to the public site. The reviewed source is versioned at <a href="https://github.com/arussellbishop/ai-ml-aws-portfolio">arussellbishop/ai-ml-aws-portfolio</a>. Original private repositories remain separate.</p></section>')
